        // Record initial balance
        uint256 initialBalance = MelodyToken(TARGET).balanceOf(attacker);

        // Get the owner address
        address owner = MelodyToken(TARGET).owner();

        // Try minting a smaller amount first - 1 token
        uint256 mintAmount = 1e18;

        // Impersonate the owner to call mint()
        vm.prank(owner);

        // Mint tokens to the attacker
        MelodyToken(TARGET).mint(attacker, mintAmount);

        // Record final balance
