        assertGt(finalBalance - initialBalance, 0, "Should have received some tokens");

        // If we successfully minted 1 token, try minting more
        if (finalBalance - initialBalance == mintAmount) {
            // Try minting a larger amount now that we know minting works
            uint256 initialBalance2 = finalBalance;

            vm.prank(owner);
            // Try minting 10,000 tokens this time
            MelodyToken(TARGET).mint(attacker, 10_000e18);

            uint256 finalBalance2 = MelodyToken(TARGET).balanceOf(attacker);
            assertGt(finalBalance2, initialBalance2, "Second mint should also increase balance");
        }
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

